#include <iostream>
#include <string>

class Account {
public:
    Account() : balance{0.0} {}
    explicit Account(double b) : balance{b} {}

    void setBalance(double balance) {
        // Param 'balance' hides class member 'Account::balance'
        if (balance >= 0.0) {
            Account::balance = balance; // Disambiguate using class scope
        }
    }

    double getBalance() const {
        return balance;
    }

private:
    double balance;
};

int main() {
    Account account;
    Account& accountRef = account;
    Account* accountPtr = &account;

    account.setBalance(100.25);
    std::cout << "Via object: " << account.getBalance() << "\n";

    accountRef.setBalance(250.50);
    std::cout << "Via reference: " << accountRef.getBalance() << "\n";

    accountPtr->setBalance(500.75);
    std::cout << "Via pointer: " << accountPtr->getBalance() << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    // Default constructor defaulting all parameters
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec);
    }

    void setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
    }

    void setHour(int h) {
        if (h >= 0 && h < 24) { hour = h; }
        else { throw std::invalid_argument("hour must be 0-23"); }
    }

    void setMinute(int m) {
        if (m >= 0 && m < 60) { minute = m; }
        else { throw std::invalid_argument("minute must be 0-59"); }
    }

    void setSecond(int s) {
        if (s >= 0 && s < 60) { second = s; }
        else { throw std::invalid_argument("second must be 0-59"); }
    }

    unsigned int getHour() const { return hour; }
    unsigned int getMinute() const { return minute; }
    unsigned int getSecond() const { return second; }

    // Predicate access function
    bool isAM() const { return hour < 12; }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << getHour() << ":"
                  << std::setw(2) << getMinute() << ":"
                  << std::setw(2) << getSecond();
    }

private:
    unsigned int hour{0};
    unsigned int minute{0};
    unsigned int second{0};
};

int main() {
    Time t1;             // All defaulted: 00:00:00
    Time t2{14};         // 14:00:00
    Time t3{21, 45};     // 21:45:00
    Time t4{8, 30, 15};  // 08:30:15

    std::cout << "t1 universal: "; t1.printUniversal(); std::cout << " (isAM: " << t1.isAM() << ")\n";
    std::cout << "t2 universal: "; t2.printUniversal(); std::cout << " (isAM: " << t2.isAM() << ")\n";
    std::cout << "t3 universal: "; t3.printUniversal(); std::cout << " (isAM: " << t3.isAM() << ")\n";
    std::cout << "t4 universal: "; t4.printUniversal(); std::cout << " (isAM: " << t4.isAM() << ")\n";

    try {
        Time tBad{25, 0, 0};
    } catch (const std::invalid_argument& ex) {
        std::cout << "Caught expected exception: " << ex.what() << "\n";
    }

    return 0;
}
